import random

class Virus:
    def __init__(self, name, mutation_rate) :
        self. name = name
        self. mutation_rate = mutation_rate

    def replicate(self, host) :
        if random. random() < self. mutation_rate :
            host. add_virus(self)
        else :
            host. remove_virus(self)

        for other_virus in host. viruses :
            if other_virus != self :
                if random. random() < self. mutation_rate :
                    host. add_virus(other_virus)
                    host. remove_virus(self)

class Host:
    def __init__(self, name) :
        self. name = name
        self. viruses = []

    def add_virus(self, virus) :
        self. viruses. append(virus)

    def remove_virus(self, virus) :
        self. viruses. remove(virus)

if __name__ == '__main__' :
    name1 = input('Enter name for first host: ')
    name2 = input('Enter name for second host: ')
    virus_rate = float(input('Enter mutation rate: '))

    host1 = Host(name1)
    host2 = Host(name2)

    virus = Virus('Virus1', virus_rate)

    for round in range(1000) :
        for virus in host1. viruses :
            virus. replicate(host1)
        for virus in host2. viruses :
            virus. replicate(host2)

        if len(host1. viruses) > 0 and len(host2. viruses) > 0 :
            print('Round %d: %s has %d viruses, %s has %d viruses.' % (round, host1. name, len(host1. viruses), host2. name, len(host2. viruses)))
        else :
            print('Round %d: %s has %d viruses, %s has %d viruses.' % (round, host1. name, len(host1. viruses), host2. name, len(host2. viruses)))
            break
